// Bundle dispatch workflow (library: no main).
//
// fulfill tries BOTH lines from `preferred`, then BOTH from `fallback`, and
// otherwise emits one `deferred` event. Each attempt is one transaction, so a
// failure after the first reservation can never leak a hold. Shortage is
// detected before reserving (exact availability check, accounting for both
// lines drawing on the same SKU), so the attempt that pauses is always one that
// reserved both holds, and any other domain failure (unknown warehouse, bad
// quantity, duplicate hold, ...) propagates unchanged with its original code,
// location and stack instead of being swallowed or masked.

proc fulfill(order: string, sku_a: string, qty_a: int,
             sku_b: string, qty_b: int, preferred: string, fallback: string) {
    if (fulfill_fits(sku_a, qty_a, sku_b, qty_b, preferred)) {
        fulfill_attempt(order, sku_a, qty_a, sku_b, qty_b, preferred);
        return;
    }
    if (fulfill_fits(sku_a, qty_a, sku_b, qty_b, fallback)) {
        fulfill_attempt(order, sku_a, qty_a, sku_b, qty_b, fallback);
        return;
    }
    emit "deferred" { order: order; reason: "SHORTAGE"; };
}

// Builtins cannot return values through procedures, so the feasibility test is
// written as an expression helper inlined at each call site via this wrapper:
// it is evaluated inside `fulfill` through `fulfill_fits` below.
