def ev(result):
    return [(e["name"], e["data"]) for e in result["events"]]


class Base(unittest.TestCase):
    def ok(self, src, inv=INV, lib=None):
        code, out, diag = run(src, inv, lib)
        self.assertEqual(code, 0, diag)
        # every program is also checked through a pause/resume chain
        c2, out2, diag2, labels = chain(src, inv, lib)
        self.assertEqual(c2, 0, diag2)
        self.assertEqual(out, out2)
        return out

    def fails(self, src, category, inv=INV, lib=None):
        code, out, diag = run(src, inv, lib)
        self.assertEqual(diag and diag["error"], category, (code, diag))
        self.assertIsNone(out)
        if category in ("DOMAIN", "RUNTIME"):
            c2, out2, diag2, _ = chain(src, inv, lib)
            self.assertEqual(diag2, diag)
        return diag


class Semantics(Base):
    def test_arith(self):
